insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('en-que-se-va-realmente-el-dinero-de-un-estudiante-durante-un-mes','negocios',array['sociedad']::text[],'¿En qué se va realmente el dinero de un estudiante durante un mes?','Registra cada gasto durante un mes, clasifícalo y descubre en qué se va realmente tu dinero, qué gastos eran necesarios y cuáles podrían cambiar.','Análisis','~15 h',15,array['Finanzas personales','Datos']::text[],array['investigar','resolver']::text[],'propios',NULL,'economia contabilidad administracion estadistica psicologia ingenieria industrial educacion sociologia registro y organizacion de datos. analisis basico de presupuestos. visualizacion de informacion. reflexion critica. hoja de calculo o libreta. un editor de graficos. una aplicacion de registro de gastos, si prefieres.',$a1sld${"id": "en-que-se-va-realmente-el-dinero-de-un-estudiante-durante-un-mes", "area": "negocios", "areas2": ["sociedad"], "titulo": "¿En qué se va realmente el dinero de un estudiante durante un mes?", "resumen": "Registra cada gasto durante un mes, clasifícalo y descubre en qué se va realmente tu dinero, qué gastos eran necesarios y cuáles podrían cambiar.", "tipo": "Análisis", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Finanzas personales", "Datos"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Economía", "Contabilidad", "Administración", "Estadística", "Psicología", "Ingeniería Industrial", "Educación", "Sociología"], "problema": ["Casi todos saben cuánto dinero les entra, pero pocos saben con certeza en qué se va. Los gastos pequeños y frecuentes, como pasajes, snacks, fotocopias o salidas, se olvidan al terminar el día y el mes parece que se esfumó.", "Sin un registro, las decisiones sobre ahorro o gasto se toman por sensación. Contar el dinero con orden permite ver patrones que a veces sorprenden."], "desarrollar": ["Durante un mes anota cada gasto con su monto, su categoría, como transporte, comida, estudios u ocio, y si fue necesario, ocasional o prescindible, con una libreta o una hoja de cálculo.", "Al final suma por categoría, grafica cómo se reparte tu dinero, identifica las tres categorías que más pesan y comenta qué te sorprendió y qué cambiarías."], "ampliaciones": [{"titulo": "Semana a semana", "aporta": "compara cómo cambia el gasto entre semanas y descubre en cuáles gastas más y por qué."}, {"titulo": "Gastos por hábito", "aporta": "separa lo que gastas por rutina de lo que gastas por impulso o por compromiso social."}, {"titulo": "Resumen para tomar decisiones", "aporta": "convierte tus datos en un tablero simple que puedas actualizar cada mes."}], "objetivos": ["Diseñar un sistema de registro sencillo y constante.", "Clasificar gastos con criterios claros.", "Visualizar la distribución del dinero.", "Reflexionar sobre qué cambiar con base en los datos."], "habilidades": ["Registro y organización de datos.", "Análisis básico de presupuestos.", "Visualización de información.", "Reflexión crítica."], "herramientas": ["Hoja de cálculo o libreta.", "Un editor de gráficos.", "Una aplicación de registro de gastos, si prefieres."], "lineamientos": ["Trabaja solo con tus propios gastos y no incluyas números de cuentas ni datos bancarios; usa montos y categorías.", "Es un ejercicio de aprendizaje y no una asesoría financiera: no tomes decisiones de deuda o inversión solo por este análisis."], "otroSector": "El mismo registro sirve para analizar el uso del tiempo, el consumo de datos móviles, la energía de un hogar o los gastos de una organización estudiantil."}$a1sld$::jsonb,9),
('disena-un-presupuesto-para-un-estudiante-con-ingresos-variables','negocios',array['sociedad']::text[],'Diseña un presupuesto para un estudiante con ingresos variables','Diseña un presupuesto mensual que funcione para quien no sabe cuánto recibirá cada mes, como quien da clases particulares, hace trabajos independientes o recibe apoyo irregular.','Plan','~18 h',18,array['Presupuesto','Ingresos variables']::text[],array['crear','resolver']::text[],'ficticios',NULL,'economia contabilidad administracion ingenieria industrial estadistica trabajo social ingenieria de sistemas educacion diseno de presupuestos. modelado en hoja de calculo. analisis de escenarios. comunicacion clara. hoja de calculo. un editor de graficos. casos inventados.',$a2sld${"id": "disena-un-presupuesto-para-un-estudiante-con-ingresos-variables", "area": "negocios", "areas2": ["sociedad"], "titulo": "Diseña un presupuesto para un estudiante con ingresos variables", "resumen": "Diseña un presupuesto mensual que funcione para quien no sabe cuánto recibirá cada mes, como quien da clases particulares, hace trabajos independientes o recibe apoyo irregular.", "tipo": "Plan", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Presupuesto", "Ingresos variables"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Economía", "Contabilidad", "Administración", "Ingeniería Industrial", "Estadística", "Trabajo Social", "Ingeniería de Sistemas", "Educación"], "problema": ["Los presupuestos clásicos suponen un ingreso fijo, pero muchos estudiantes tienen ingresos que cambian: un mes sube por un encargo y al siguiente casi no hay. En ese escenario es fácil gastar de más en un mes bueno y quedarse corto después.", "Un buen presupuesto para ingresos variables define qué es lo primero que se cubre, cuánto se guarda de lo extra y cómo se actúa en un mes flojo."], "desarrollar": ["Inventa el caso de un estudiante con ingresos que cambian entre un mínimo y un máximo, con gastos fijos y variables, y diseña un presupuesto con reglas claras, como el orden en que se pagan las prioridades y qué porcentaje de lo extra se guarda.", "Pruébalo con tres meses simulados, uno malo, uno normal y uno bueno, ajusta lo que no funcione y presenta una hoja sencilla con las reglas y un ejemplo."], "ampliaciones": [{"titulo": "Ingreso mínimo seguro", "aporta": "calcula cuánto necesita asegurar como mínimo para no entrar en problemas."}, {"titulo": "Fondo de amortiguación", "aporta": "diseña un pequeño fondo que cubra los meses flojos."}, {"titulo": "Versión con una meta", "aporta": "añade una meta de ahorro y mira cómo cambia el presupuesto."}], "objetivos": ["Definir prioridades de gasto.", "Establecer reglas para el ingreso extra.", "Probar el presupuesto en varios escenarios.", "Presentarlo de forma clara."], "habilidades": ["Diseño de presupuestos.", "Modelado en hoja de cálculo.", "Análisis de escenarios.", "Comunicación clara."], "herramientas": ["Hoja de cálculo.", "Un editor de gráficos.", "Casos inventados."], "lineamientos": ["Usa un caso inventado, no datos de personas reales, y aclara que es un modelo de ejemplo y no una recomendación personalizada.", "No incluyas productos de deuda ni de inversión como solución sin explicar sus riesgos."], "otroSector": "La misma lógica sirve para negocios con ventas irregulares, organizaciones con aportes variables o proyectos con financiamiento incierto."}$a2sld$::jsonb,10),
('cuanto-cuesta-realmente-estudiar-una-carrera-hasta-terminarla','negocios',array['educacion','sociedad']::text[],'¿Cuánto cuesta realmente estudiar una carrera hasta terminarla?','Calcula todo lo que implica estudiar una carrera, de matrícula a transporte, materiales, comida y tiempo, y descubre cuánto cuesta realmente llegar al título.','Análisis','~22 h',22,array['Educación','Costos']::text[],array['investigar','resolver']::text[],'publicos',NULL,'economia contabilidad administracion educacion estadistica sociologia ingenieria industrial ingenieria de sistemas analisis de costos. busqueda de informacion. proyeccion con supuestos. comunicacion de resultados. hoja de calculo. tarifas y reglamentos publicos de instituciones educativas. un editor de graficos.',$a3sld${"id": "cuanto-cuesta-realmente-estudiar-una-carrera-hasta-terminarla", "area": "negocios", "areas2": ["educacion", "sociedad"], "titulo": "¿Cuánto cuesta realmente estudiar una carrera hasta terminarla?", "resumen": "Calcula todo lo que implica estudiar una carrera, de matrícula a transporte, materiales, comida y tiempo, y descubre cuánto cuesta realmente llegar al título.", "tipo": "Análisis", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Educación", "Costos"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Economía", "Contabilidad", "Administración", "Educación", "Estadística", "Sociología", "Ingeniería Industrial", "Ingeniería de Sistemas"], "problema": ["Cuando se habla del costo de estudiar, casi siempre se piensa en la pensión o la matrícula. Pero hay muchos otros gastos: transporte diario, materiales, copias, comida fuera de casa, equipos, internet, y el tiempo que se dedica en lugar de trabajar.", "Al no sumarlos, las familias y los estudiantes subestiman lo que viene. Hacer la cuenta completa ayuda a planificar y a entender por qué algunos abandonan."], "desarrollar": ["Elige una carrera y una institución, real o inventada, y con información pública y estimaciones razonables calcula el costo por ciclo de matrícula o pensiones, transporte, materiales, alimentación y otros gastos.", "Proyecta el total hasta terminar la carrera con un rango, de mínimo a máximo, indica qué supuestos usaste y presenta un resumen con gráficos y una lista de los gastos que más pesan."], "ampliaciones": [{"titulo": "Costo del tiempo", "aporta": "añade lo que se dejaría de ganar si se estudia a tiempo completo."}, {"titulo": "Comparar carreras", "aporta": "compara el costo total de dos carreras o dos instituciones."}, {"titulo": "Maneras de reducirlo", "aporta": "investiga becas y ayudas que podrían disminuir el costo."}], "objetivos": ["Identificar todos los componentes del costo.", "Buscar datos públicos y justificarlos.", "Proyectar un total con un rango.", "Comunicar los supuestos con claridad."], "habilidades": ["Análisis de costos.", "Búsqueda de información.", "Proyección con supuestos.", "Comunicación de resultados."], "herramientas": ["Hoja de cálculo.", "Tarifas y reglamentos públicos de instituciones educativas.", "Un editor de gráficos."], "lineamientos": ["Cita el origen de cada dato y marca lo que son estimaciones; no incluyas información personal de familias ni cuentas bancarias.", "Evita concluir que una carrera «vale» más o menos que otra: el análisis es de costos, no de valor."], "otroSector": "El mismo análisis sirve para estimar el costo total de una capacitación, de un posgrado, de un emprendimiento o de cualquier proyecto de largo plazo."}$a3sld$::jsonb,11),
('gastos-pequenos-e-invisibles-de-la-vida-universitaria','negocios',array['sociedad']::text[],'Gastos pequeños e invisibles de la vida universitaria','Descubre qué gastos pequeños y poco visibles, como copias, pasajes sueltos, café, cargadores o suscripciones, terminan sumando una parte importante de lo que cuesta ser universitario.','Análisis','~15 h',15,array['Gastos','Vida universitaria']::text[],array['investigar','resolver']::text[],'propios',NULL,'economia contabilidad administracion psicologia sociologia estadistica educacion comunicaciones registro de datos. proyeccion simple. analisis de habitos de consumo. comunicacion clara. hoja de calculo o libreta. un editor de graficos. un formulario anonimo, si comparas con otros.',$a4sld${"id": "gastos-pequenos-e-invisibles-de-la-vida-universitaria", "area": "negocios", "areas2": ["sociedad"], "titulo": "Gastos pequeños e invisibles de la vida universitaria", "resumen": "Descubre qué gastos pequeños y poco visibles, como copias, pasajes sueltos, café, cargadores o suscripciones, terminan sumando una parte importante de lo que cuesta ser universitario.", "tipo": "Análisis", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Gastos", "Vida universitaria"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Economía", "Contabilidad", "Administración", "Psicología", "Sociología", "Estadística", "Educación", "Comunicaciones"], "problema": ["Un gasto pequeño no parece importar: un café, una copia, un pasaje extra. Pero cuando ocurren varias veces por semana, al final del mes suman más que algo que sí se planificó.", "Además hay gastos invisibles que casi nunca se cuentan, como los de tiempo perdido, las multas por entregar tarde o las compras de última hora."], "desarrollar": ["Durante dos semanas registra todo gasto menor a una cantidad que tú defines, como unos pocos soles, con su motivo y si era previsible.", "Multiplica cada tipo de gasto por las semanas del ciclo, muestra cuáles suman más de lo que imaginabas, y propón tres ajustes simples sin renunciar a lo que valoras."], "ampliaciones": [{"titulo": "Ciclo completo", "aporta": "proyecta tus gastos pequeños a un ciclo universitario."}, {"titulo": "Lo que sí vale la pena", "aporta": "identifica qué gastos pequeños sí te aportan algo importante y cuáles no."}, {"titulo": "Comparar con otros", "aporta": "compara con un grupo pequeño de compañeros, de forma anónima, qué gastos son comunes."}], "objetivos": ["Definir qué se considera un gasto pequeño.", "Registrar con constancia.", "Proyectar el efecto acumulado.", "Elegir ajustes razonables."], "habilidades": ["Registro de datos.", "Proyección simple.", "Análisis de hábitos de consumo.", "Comunicación clara."], "herramientas": ["Hoja de cálculo o libreta.", "Un editor de gráficos.", "Un formulario anónimo, si comparas con otros."], "lineamientos": ["Trabaja con tus propios gastos; si comparas con otras personas, hazlo de forma anónima y voluntaria.", "No juzgues los gastos de nadie: lo importante es entender, no recortar todo lo que da gusto."], "otroSector": "El mismo enfoque sirve para estudiar pérdidas pequeñas y repetidas en un negocio, en el uso del tiempo o en el consumo de recursos de una institución."}$a4sld$::jsonb,12),
('como-ahorrar-cuando-los-ingresos-son-limitados','negocios',array['sociedad']::text[],'¿Cómo ahorrar cuando los ingresos son limitados?','Diseña una estrategia de ahorro para alguien con poco dinero disponible, que reduzca gastos innecesarios sin quitarle lo esencial ni generarle culpa.','Plan','~20 h',20,array['Ahorro','Presupuesto']::text[],array['resolver','crear']::text[],'ficticios',NULL,'economia contabilidad administracion psicologia trabajo social ingenieria industrial estadistica educacion planificacion financiera personal. simulacion en hoja de calculo. diseno de habitos. comunicacion clara. hoja de calculo. casos inventados. un editor de graficos.',$a5sld${"id": "como-ahorrar-cuando-los-ingresos-son-limitados", "area": "negocios", "areas2": ["sociedad"], "titulo": "¿Cómo ahorrar cuando los ingresos son limitados?", "resumen": "Diseña una estrategia de ahorro para alguien con poco dinero disponible, que reduzca gastos innecesarios sin quitarle lo esencial ni generarle culpa.", "tipo": "Plan", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Ahorro", "Presupuesto"], "intencion": ["resolver", "crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Economía", "Contabilidad", "Administración", "Psicología", "Trabajo Social", "Ingeniería Industrial", "Estadística", "Educación"], "problema": ["Los consejos de ahorro suelen ser genéricos y poco realistas: «ahorra el diez por ciento» no tiene mucho sentido cuando casi todo se va en lo básico. Cuando el margen es pequeño, cada decisión pesa.", "Una estrategia útil parte de lo que se puede cambiar, empieza con montos posibles y se sostiene sin sentirse castigo."], "desarrollar": ["Inventa dos casos de personas con ingresos limitados pero distintos, con sus gastos fijos y variables, y para cada una identifica qué gastos son esenciales, cuáles ajustables y cuáles prescindibles.", "Diseña una estrategia con tres o cuatro reglas concretas, por ejemplo qué guardar primero, qué cambiar por una alternativa más barata y qué revisar cada semana, y simula un trimestre para ver cuánto se lograría."], "ampliaciones": [{"titulo": "Medir la dificultad", "aporta": "estima cuánto cuesta cada cambio en comodidad o tiempo."}, {"titulo": "Alternativas más baratas", "aporta": "investiga opciones más económicas para tres gastos habituales."}, {"titulo": "Versión visual", "aporta": "resume la estrategia en una hoja que se pueda pegar y consultar."}], "objetivos": ["Distinguir gastos esenciales de ajustables.", "Diseñar reglas posibles y sostenibles.", "Simular su efecto.", "Presentar la estrategia con claridad."], "habilidades": ["Planificación financiera personal.", "Simulación en hoja de cálculo.", "Diseño de hábitos.", "Comunicación clara."], "herramientas": ["Hoja de cálculo.", "Casos inventados.", "Un editor de gráficos."], "lineamientos": ["Trabaja con casos inventados y no con datos de personas reales; explica que es un ejemplo y no una asesoría personalizada.", "No sugieras recortar gastos de salud, seguridad o alimentación básica para ahorrar."], "otroSector": "La misma estrategia de priorizar con recursos escasos sirve para el tiempo, la energía o el presupuesto de una organización pequeña."}$a5sld$::jsonb,13),
('el-reto-de-ahorrar-para-una-meta-especifica','negocios',array['sociedad']::text[],'El reto de ahorrar para una meta específica','Elige algo concreto que quieras lograr, calcula cuánto cuesta y cuánto necesitas apartar cada semana, y prueba durante unas semanas qué estrategia te funciona.','Plan','4 a 8 semanas',25,array['Ahorro','Metas']::text[],array['resolver','crear']::text[],'propios',NULL,'economia psicologia administracion contabilidad educacion estadistica comunicaciones ingenieria industrial planificacion de metas. seguimiento de indicadores. autoevaluacion. comunicacion de resultados. hoja de calculo o libreta. un grafico de avance. precios de lo que quieres comprar.',$a6sld${"id": "el-reto-de-ahorrar-para-una-meta-especifica", "area": "negocios", "areas2": ["sociedad"], "titulo": "El reto de ahorrar para una meta específica", "resumen": "Elige algo concreto que quieras lograr, calcula cuánto cuesta y cuánto necesitas apartar cada semana, y prueba durante unas semanas qué estrategia te funciona.", "tipo": "Plan", "tiempo": "4 a 8 semanas", "horas": 25, "etiquetas": ["Ahorro", "Metas"], "intencion": ["resolver", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Economía", "Psicología", "Administración", "Contabilidad", "Educación", "Estadística", "Comunicaciones", "Ingeniería Industrial"], "problema": ["Ahorrar «para algo» es más fácil que ahorrar sin un objetivo, pero la mayoría de las metas se quedan en deseos porque no se calculan: cuánto cuesta, en cuánto tiempo y de dónde sale ese dinero.", "Un reto con meta y seguimiento permite aprender qué estrategias funcionan para ti y por qué otras se abandonan."], "desarrollar": ["Elige una meta realista, como un equipo, un curso o un viaje corto, averigua su costo, define un plazo y calcula cuánto necesitarías apartar cada semana.", "Durante varias semanas aplica una estrategia, como apartar al recibir dinero o reducir un gasto concreto, registra tu avance en un gráfico y concluye qué funcionó, qué no y qué ajustarías."], "ampliaciones": [{"titulo": "Comparar estrategias", "aporta": "prueba dos estrategias distintas en semanas distintas y compáralas."}, {"titulo": "Imprevistos", "aporta": "añade qué pasa cuando aparece un gasto no previsto y cómo se absorbe."}, {"titulo": "Tablero de avance", "aporta": "crea un tablero visual que muestre el progreso hacia la meta."}], "objetivos": ["Definir una meta medible.", "Calcular el aporte necesario.", "Registrar el avance con constancia.", "Evaluar qué estrategia funcionó."], "habilidades": ["Planificación de metas.", "Seguimiento de indicadores.", "Autoevaluación.", "Comunicación de resultados."], "herramientas": ["Hoja de cálculo o libreta.", "Un gráfico de avance.", "Precios de lo que quieres comprar."], "lineamientos": ["Elige una meta realista que no te obligue a recortar lo esencial, y no pidas préstamos ni uses productos financieros para el reto.", "Es un ejercicio personal: no lo uses para comparar ni para presionar a nadie."], "otroSector": "El mismo método sirve para metas de estudio, de salud, de un proyecto o de recaudación de fondos de una organización."}$a6sld$::jsonb,14),
('cuanto-cuesta-comprar-en-cuotas-frente-a-pagar-al-contado','negocios',array['sociedad']::text[],'¿Cuánto cuesta comprar en cuotas frente a pagar al contado?','Calcula cuánto termina costando un producto comprado en cuotas, con intereses y cargos, y compáralo con el precio al contado para decidir cuándo conviene cada opción.','Análisis','~18 h',18,array['Crédito','Cuotas']::text[],array['investigar','resolver']::text[],'publicos',NULL,'economia contabilidad administracion estadistica ingenieria industrial derecho matematica ingenieria de sistemas calculo financiero basico. busqueda de informacion. analisis comparativo. comunicacion clara. hoja de calculo. tarifarios y simuladores publicos. un editor de graficos.',$a7sld${"id": "cuanto-cuesta-comprar-en-cuotas-frente-a-pagar-al-contado", "area": "negocios", "areas2": ["sociedad"], "titulo": "¿Cuánto cuesta comprar en cuotas frente a pagar al contado?", "resumen": "Calcula cuánto termina costando un producto comprado en cuotas, con intereses y cargos, y compáralo con el precio al contado para decidir cuándo conviene cada opción.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Crédito", "Cuotas"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Economía", "Contabilidad", "Administración", "Estadística", "Ingeniería Industrial", "Derecho", "Matemática", "Ingeniería de Sistemas"], "problema": ["Pagar en cuotas hace que algo caro parezca accesible, pero la suma de las cuotas casi siempre es mayor que el precio al contado. Los intereses, comisiones y seguros no siempre se muestran con claridad, y es difícil compararlos.", "Entender cuánto cuesta realmente el crédito ayuda a decidir con información, y a veces comprar en cuotas sí tiene sentido."], "desarrollar": ["Elige tres compras típicas, como un celular, una laptop o un electrodoméstico, busca con información pública sus precios al contado y sus planes en cuotas, con tasas y cargos publicados.", "Calcula el costo total en cuotas, la diferencia con el contado y el costo por cada mes de financiamiento, y concluye en qué situaciones conviene y en cuáles no, con una tabla comparativa."], "ampliaciones": [{"titulo": "Calculadora de cuotas", "aporta": "crea una hoja donde se escriba precio y plazo y muestre el costo total."}, {"titulo": "Efecto de un atraso", "aporta": "estima cuánto sube el costo si se paga tarde."}, {"titulo": "Alternativas", "aporta": "compara con ahorrar durante unos meses antes de comprar."}], "objetivos": ["Reunir información pública de precios y tasas.", "Calcular el costo total del financiamiento.", "Comparar con el pago al contado.", "Explicar claramente cuándo conviene cada opción."], "habilidades": ["Cálculo financiero básico.", "Búsqueda de información.", "Análisis comparativo.", "Comunicación clara."], "herramientas": ["Hoja de cálculo.", "Tarifarios y simuladores públicos.", "Un editor de gráficos."], "lineamientos": ["Usa precios y tasas publicados y cita la fecha; no recomiendes productos financieros concretos ni empresas.", "Aclara que es un ejercicio educativo y no una asesoría financiera, y que las condiciones reales cambian."], "otroSector": "El mismo cálculo sirve para evaluar alquilar frente a comprar, pagar anual frente a mensual o comprar al por mayor frente a por menor."}$a7sld$::jsonb,15),
('el-costo-total-de-tener-un-producto-durante-varios-anos','negocios',array['ambiente','industria']::text[],'El costo total de tener un producto durante varios años','Descubre cuánto cuesta realmente tener un producto, sumando precio, uso, mantenimiento y reemplazo, y comprueba si el más barato al comprar es el más barato al final.','Análisis','~18 h',18,array['Costo total','Consumo']::text[],array['investigar','resolver']::text[],'publicos',NULL,'economia ingenieria industrial contabilidad administracion ingenieria mecanica estadistica ingenieria electronica ingenieria de sistemas analisis de costos. calculo en hoja de calculo. busqueda de datos. comunicacion de resultados. hoja de calculo. fichas tecnicas y precios publicados. un editor de graficos.',$a8sld${"id": "el-costo-total-de-tener-un-producto-durante-varios-anos", "area": "negocios", "areas2": ["ambiente", "industria"], "titulo": "El costo total de tener un producto durante varios años", "resumen": "Descubre cuánto cuesta realmente tener un producto, sumando precio, uso, mantenimiento y reemplazo, y comprueba si el más barato al comprar es el más barato al final.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Costo total", "Consumo"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Economía", "Ingeniería Industrial", "Contabilidad", "Administración", "Ingeniería Mecánica", "Estadística", "Ingeniería Electrónica", "Ingeniería de Sistemas"], "problema": ["Al comprar, casi siempre se compara el precio de venta. Pero un producto cuesta también lo que gasta al usarse, lo que se paga por repararlo y cada cuánto hay que reemplazarlo.", "Un celular, una laptop o una moto baratos pueden salir más caros en tres años que uno de mayor precio. Esa cuenta rara vez se hace."], "desarrollar": ["Elige un producto de uso común y dos alternativas, una barata y una más cara, y reúne con información pública su precio, su consumo o gasto de uso, el costo de mantenimiento y su duración esperada.", "Calcula el costo total en el periodo que consideres razonable, compara con una tabla y un gráfico y concluye cuál conviene según el uso que tendría."], "ampliaciones": [{"titulo": "Valor de reventa", "aporta": "incluye cuánto podría recuperarse al venderlo después."}, {"titulo": "Cambiar el uso", "aporta": "calcula cómo cambia el resultado si se usa más o menos de lo previsto."}, {"titulo": "Costo por uso", "aporta": "convierte el costo total en un costo por día o por vez de uso."}], "objetivos": ["Identificar todos los costos de poseer un producto.", "Reunir datos con fuentes.", "Calcular y comparar el costo total.", "Explicar los supuestos."], "habilidades": ["Análisis de costos.", "Cálculo en hoja de cálculo.", "Búsqueda de datos.", "Comunicación de resultados."], "herramientas": ["Hoja de cálculo.", "Fichas técnicas y precios publicados.", "Un editor de gráficos."], "lineamientos": ["Cita los precios con su fecha y marca lo que son estimaciones de duración y de uso; no recomiendes marcas concretas.", "Aclara que el resultado depende del uso de cada persona y no es una conclusión general."], "otroSector": "El mismo análisis sirve para evaluar maquinaria, software, vehículos de una empresa o equipamiento de una oficina."}$a8sld$::jsonb,16),
('cuanto-cuesta-moverte-transporte-propio-frente-a-publico','negocios',array['ciudades','ambiente']::text[],'¿Cuánto cuesta moverte? Transporte propio frente a público','Registra y compara el costo real de tus traslados durante una semana, sumando pasajes, combustible, mantenimiento, estacionamiento y tiempo, para ver qué opción conviene.','Análisis','~20 h',20,array['Transporte','Costos']::text[],array['investigar','resolver']::text[],'propios',NULL,'economia ingenieria industrial ingenieria civil contabilidad administracion estadistica geografia ingenieria ambiental registro de datos. analisis de costos. calculo por unidad. comunicacion de resultados. hoja de calculo. una aplicacion de mapas. tarifas publicas de transporte.',$a9sld${"id": "cuanto-cuesta-moverte-transporte-propio-frente-a-publico", "area": "negocios", "areas2": ["ciudades", "ambiente"], "titulo": "¿Cuánto cuesta moverte? Transporte propio frente a público", "resumen": "Registra y compara el costo real de tus traslados durante una semana, sumando pasajes, combustible, mantenimiento, estacionamiento y tiempo, para ver qué opción conviene.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Transporte", "Costos"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Economía", "Ingeniería Industrial", "Ingeniería Civil", "Contabilidad", "Administración", "Estadística", "Geografía", "Ingeniería Ambiental"], "problema": ["Mucha gente cree que tener moto o auto es más barato que el transporte público, o al revés, sin haber hecho la cuenta completa. Hay costos visibles, como el pasaje o la gasolina, y otros ocultos, como el mantenimiento, el seguro o el tiempo.", "No todos pueden elegir: depende de la distancia, la seguridad y los horarios. Pero conocer los costos reales permite decidir mejor y entender por qué ciertas rutas pesan tanto en el presupuesto."], "desarrollar": ["Durante una semana anota cada traslado con su costo, su duración y el medio usado, y estima los costos que no pagas cada día, como mantenimiento o depreciación si usas un vehículo propio.", "Calcula el costo por semana, por mes y por kilómetro, compara con otra alternativa realista para el mismo recorrido y presenta una conclusión con sus límites."], "ampliaciones": [{"titulo": "Valor del tiempo", "aporta": "añade cuánto cuesta el tiempo de viaje según lo que podrías hacer en ese tiempo."}, {"titulo": "Transporte compartido", "aporta": "calcula cuánto cambia el costo si se comparte el vehículo."}, {"titulo": "Un año completo", "aporta": "proyecta los costos de movilidad durante un año."}], "objetivos": ["Registrar traslados con método.", "Identificar costos visibles y ocultos.", "Comparar alternativas.", "Presentar las conclusiones con claridad."], "habilidades": ["Registro de datos.", "Análisis de costos.", "Cálculo por unidad.", "Comunicación de resultados."], "herramientas": ["Hoja de cálculo.", "Una aplicación de mapas.", "Tarifas públicas de transporte."], "lineamientos": ["Prioriza tu seguridad: la opción más barata no debe ser la menos segura, y no recomiendes manejar sin licencia ni conducir de forma riesgosa.", "Usa tus propios datos o ejemplos inventados, sin registrar placas ni datos de otras personas."], "otroSector": "El mismo análisis sirve para comparar costos de envío, de logística de una empresa o de viajes de trabajo."}$a9sld$::jsonb,17),
('disena-tu-fondo-de-emergencia-ideal','negocios',array['sociedad']::text[],'Diseña tu fondo de emergencia ideal','Calcula cuánto dinero necesitaría apartar una persona para enfrentar un imprevisto, cómo lo juntaría poco a poco y dónde lo mantendría, con casos ficticios.','Plan','~18 h',18,array['Ahorro','Imprevistos']::text[],array['crear','resolver']::text[],'ficticios',NULL,'economia contabilidad administracion psicologia estadistica trabajo social ingenieria industrial educacion planificacion financiera. calculo en hoja de calculo. analisis de escenarios. comunicacion clara. hoja de calculo. casos inventados. un editor de graficos.',$a10sld${"id": "disena-tu-fondo-de-emergencia-ideal", "area": "negocios", "areas2": ["sociedad"], "titulo": "Diseña tu fondo de emergencia ideal", "resumen": "Calcula cuánto dinero necesitaría apartar una persona para enfrentar un imprevisto, cómo lo juntaría poco a poco y dónde lo mantendría, con casos ficticios.", "tipo": "Plan", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Ahorro", "Imprevistos"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Economía", "Contabilidad", "Administración", "Psicología", "Estadística", "Trabajo Social", "Ingeniería Industrial", "Educación"], "problema": ["Los imprevistos, como una reparación, una consulta o un pasaje urgente, llegan sin avisar. Quien no tiene un colchón suele endeudarse o dejar de pagar algo importante.", "Pero «ahorra para emergencias» no dice cuánto ni cómo. El monto adecuado depende de los gastos fijos, de la estabilidad de los ingresos y de lo que cada persona considera una emergencia."], "desarrollar": ["Inventa dos personas con situaciones distintas y define para cada una qué sería una emergencia, cuáles son sus gastos mínimos mensuales y cuántos meses de colchón sería razonable apuntar.", "Diseña un plan para llegar a ese monto en un plazo realista, con aportes pequeños, y explica dónde convendría mantenerlo para que esté disponible sin tentación de gastarlo."], "ampliaciones": [{"titulo": "Distintos tamaños", "aporta": "diseña una versión mínima, una media y una completa del fondo."}, {"titulo": "Usarlo y reponerlo", "aporta": "define reglas de cuándo usarlo y cómo se repone después."}, {"titulo": "Simulación de un imprevisto", "aporta": "simula qué pasa con y sin fondo ante un mismo imprevisto."}], "objetivos": ["Definir qué es una emergencia.", "Calcular un monto razonable con criterios claros.", "Diseñar un plan de aportes.", "Simular su efecto."], "habilidades": ["Planificación financiera.", "Cálculo en hoja de cálculo.", "Análisis de escenarios.", "Comunicación clara."], "herramientas": ["Hoja de cálculo.", "Casos inventados.", "Un editor de gráficos."], "lineamientos": ["Trabaja con casos inventados y explica que es un ejemplo y no una asesoría financiera personalizada.", "No recomiendes productos financieros ni inversiones concretas para el fondo."], "otroSector": "El mismo concepto de reserva ante lo inesperado sirve para el inventario de un negocio, el tiempo de un proyecto o la caja de una organización."}$a10sld$::jsonb,18),
('cuanto-cuesta-mantener-un-hobby','negocios',array['sociedad','arte']::text[],'¿Cuánto cuesta mantener un hobby?','Calcula cuánto cuesta realmente un pasatiempo, desde lo que se compra hasta lo que se gasta en usarlo y mantenerlo, y qué se obtiene a cambio.','Análisis','~12 h',12,array['Ocio','Costos']::text[],array['investigar']::text[],'propios',NULL,'economia administracion contabilidad psicologia estadistica comunicaciones sociologia educacion analisis de costos. calculo por unidad. comparacion de alternativas. reflexion critica. hoja de calculo. registros o recuerdos de gastos. un editor de graficos.',$a11sld${"id": "cuanto-cuesta-mantener-un-hobby", "area": "negocios", "areas2": ["sociedad", "arte"], "titulo": "¿Cuánto cuesta mantener un hobby?", "resumen": "Calcula cuánto cuesta realmente un pasatiempo, desde lo que se compra hasta lo que se gasta en usarlo y mantenerlo, y qué se obtiene a cambio.", "tipo": "Análisis", "tiempo": "~12 h", "horas": 12, "etiquetas": ["Ocio", "Costos"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Economía", "Administración", "Contabilidad", "Psicología", "Estadística", "Comunicaciones", "Sociología", "Educación"], "problema": ["Un hobby parece barato al empezar, pero con el tiempo se suman equipos, accesorios, cursos, entradas, reparaciones y reemplazos. Pocas veces se hace la cuenta, porque se disfruta y no se piensa como un gasto.", "Conocer el costo real ayuda a decidir cuánto vale la pena invertir y a descubrir opciones más baratas para lo mismo."], "desarrollar": ["Elige un hobby tuyo o de alguien cercano con su permiso y lista todo lo que se ha gastado en el último año, dividiéndolo en compra inicial, consumibles, mantenimiento y otros.", "Calcula el costo por mes y por vez que se practica, compara con alternativas más económicas y concluye qué parte del gasto realmente aporta disfrute."], "ampliaciones": [{"titulo": "Primer año frente a los siguientes", "aporta": "compara cuánto cuesta empezar con cuánto cuesta continuar."}, {"titulo": "Compartir recursos", "aporta": "analiza cómo cambia el costo si se comparten equipos con otras personas."}, {"titulo": "Comparar hobbies", "aporta": "compara el costo por hora de disfrute de dos pasatiempos."}], "objetivos": ["Listar costos con orden.", "Calcular costos por unidad de uso.", "Comparar alternativas.", "Reflexionar sobre el valor que se obtiene."], "habilidades": ["Análisis de costos.", "Cálculo por unidad.", "Comparación de alternativas.", "Reflexión crítica."], "herramientas": ["Hoja de cálculo.", "Registros o recuerdos de gastos.", "Un editor de gráficos."], "lineamientos": ["Usa tus propios datos o los de alguien cercano con su permiso; evita comparar el valor de los pasatiempos de otras personas.", "No lo uses para decidir dejar un pasatiempo que te hace bien solo por su costo."], "otroSector": "El mismo cálculo sirve para costos de un equipo deportivo, de un servicio de suscripción o de un proyecto personal de largo plazo."}$a11sld$::jsonb,19),
('cuanto-cuesta-vivir-de-forma-independiente','negocios',array['sociedad']::text[],'¿Cuánto cuesta vivir de forma independiente?','Estima cuánto dinero necesita una persona joven para vivir sola o compartiendo vivienda en tu ciudad, con alquiler, servicios, comida y transporte.','Análisis','~22 h',22,array['Costo de vida','Independencia']::text[],array['investigar','resolver']::text[],'publicos',NULL,'economia contabilidad administracion sociologia estadistica arquitectura psicologia trabajo social busqueda de informacion. presupuesto y proyeccion. analisis comparativo. comunicacion clara. hoja de calculo. portales publicos de precios y avisos. un editor de graficos.',$a12sld${"id": "cuanto-cuesta-vivir-de-forma-independiente", "area": "negocios", "areas2": ["sociedad"], "titulo": "¿Cuánto cuesta vivir de forma independiente?", "resumen": "Estima cuánto dinero necesita una persona joven para vivir sola o compartiendo vivienda en tu ciudad, con alquiler, servicios, comida y transporte.", "tipo": "Análisis", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Costo de vida", "Independencia"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Economía", "Contabilidad", "Administración", "Sociología", "Estadística", "Arquitectura", "Psicología", "Trabajo Social"], "problema": ["Muchos jóvenes sueñan con independizarse, pero casi nunca calculan qué implica: alquiler, garantía, servicios, comida, transporte, internet y gastos imprevistos. Subestimar esa cuenta lleva a decisiones apresuradas o a volver a casa.", "Entender los números ayuda a planear y a ver qué ingresos serían necesarios, y qué cambia al compartir el costo con otras personas."], "desarrollar": ["Con información pública de precios de alquiler, servicios y alimentos de tu ciudad, arma un presupuesto mensual de una persona que vive sola y otro de tres personas que comparten vivienda, con rangos de mínimo y máximo.", "Calcula el ingreso necesario en cada caso, compara los resultados y señala qué gastos tienen mayor peso y qué supuestos usaste."], "ampliaciones": [{"titulo": "Costo de arrancar", "aporta": "calcula cuánto dinero se necesita antes de mudarse, como garantías y muebles básicos."}, {"titulo": "Distintos barrios", "aporta": "compara el costo en dos zonas diferentes de la ciudad."}, {"titulo": "Escenarios de ingresos", "aporta": "analiza con qué ingreso mensual el presupuesto sería sostenible."}], "objetivos": ["Reunir datos públicos de precios.", "Armar presupuestos con rangos.", "Comparar escenarios.", "Explicar los supuestos."], "habilidades": ["Búsqueda de información.", "Presupuesto y proyección.", "Análisis comparativo.", "Comunicación clara."], "herramientas": ["Hoja de cálculo.", "Portales públicos de precios y avisos.", "Un editor de gráficos."], "lineamientos": ["Usa precios publicados como referencia y fecha cada dato; no uses información personal de arrendadores ni de inquilinos.", "Aclara que son estimaciones para aprender y no un plan personal de mudanza."], "otroSector": "El mismo método sirve para estimar el costo de abrir una oficina, de iniciar un negocio en otra ciudad o de mudarse por estudios."}$a12sld$::jsonb,20),
('cuanto-cuesta-cocinar-en-casa-frente-a-comprar-la-comida','negocios',array['agricultura','salud']::text[],'¿Cuánto cuesta cocinar en casa frente a comprar la comida?','Compara el costo real de preparar una comida en casa con el de comprarla hecha, incluyendo ingredientes, gas, tiempo y desperdicio.','Análisis','~18 h',18,array['Alimentación','Costos']::text[],array['investigar','resolver']::text[],'propios',NULL,'economia administracion nutricion ingenieria agroindustrial contabilidad estadistica ingenieria industrial educacion analisis de costos. calculo por porcion. planificacion. comunicacion de resultados. hoja de calculo. precios de mercado y recetas. un editor de graficos.',$a13sld${"id": "cuanto-cuesta-cocinar-en-casa-frente-a-comprar-la-comida", "area": "negocios", "areas2": ["agricultura", "salud"], "titulo": "¿Cuánto cuesta cocinar en casa frente a comprar la comida?", "resumen": "Compara el costo real de preparar una comida en casa con el de comprarla hecha, incluyendo ingredientes, gas, tiempo y desperdicio.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Alimentación", "Costos"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Economía", "Administración", "Nutrición", "Ingeniería Agroindustrial", "Contabilidad", "Estadística", "Ingeniería Industrial", "Educación"], "problema": ["Se suele decir que cocinar en casa es más barato, pero casi nunca se hace la cuenta con todo: ingredientes, gas, tiempo de preparación, utensilios y lo que sobra o se desperdicia. Del otro lado, comprar comida preparada tiene su propio costo oculto.", "El resultado depende de qué se cocina, para cuántas personas y con qué frecuencia."], "desarrollar": ["Elige tres comidas comunes en tu entorno, como un almuerzo, un desayuno y una cena, y para cada una calcula el costo de prepararla en casa sumando ingredientes, gas y desperdicio estimado, y el de comprarla hecha.", "Compara por porción y por semana, estima también el tiempo que toma cada opción, y presenta cuándo conviene cocinar, cuándo comprar y cuándo una mezcla de ambas."], "ampliaciones": [{"titulo": "Cocinar para varios", "aporta": "calcula cómo baja el costo por porción al cocinar para más personas."}, {"titulo": "Planificar el menú", "aporta": "diseña un menú semanal y calcula su costo."}, {"titulo": "Costo del tiempo", "aporta": "añade el valor que le das a tu tiempo."}], "objetivos": ["Identificar todos los costos de cada opción.", "Calcular costos por porción.", "Comparar con criterios claros.", "Explicar los límites del análisis."], "habilidades": ["Análisis de costos.", "Cálculo por porción.", "Planificación.", "Comunicación de resultados."], "herramientas": ["Hoja de cálculo.", "Precios de mercado y recetas.", "Un editor de gráficos."], "lineamientos": ["Usa precios reales de tu zona con su fecha y no hagas recomendaciones nutricionales ni de salud: el análisis es de costos.", "Considera la higiene y la seguridad en la preparación de alimentos si pruebas las recetas."], "otroSector": "El mismo análisis sirve para decidir entre hacer o comprar en un negocio, como producir una pieza propia o contratarla a un proveedor."}$a13sld$::jsonb,21)
